import dafny_marshal as M
import F3__1__REQ__1Domain as core
Dom = core.default__

from fastapi import APIRouter, HTTPException
from sqlalchemy import Column, Integer, String, Text
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import Session
from app.extensions import Base, SessionLocal, engine
import json

class AppState(Base):
    __tablename__ = "app_state"
    id = Column(Integer, primary_key=True)
    key = Column(String, unique=True)
    value = Column(Text)

Base.metadata.create_all(engine)

router = APIRouter()

def get_db_session() -> Session:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def load_state(db: Session) -> Dom.Model:
    state_row = db.query(AppState).filter(AppState.key == "state").first()
    if state_row is None:
        return Dom.Init()
    return M.from_str(state_row.value)


def save_state(db: Session, model: Dom.Model) -> None:
    state_json = M.to_str(model)
    state_row = db.query(AppState).filter(AppState.key == "state").first()
    if state_row is None:
        state_row = AppState(key="state", value=state_json)
        db.add(state_row)
    else:
        state_row.value = state_json
    db.commit()


def search_torrents_and_streaming(query: str) -> dict[str, list[dict[str, str]]]:
    with next(get_db_session()) as db:
        model = load_state(db)
        action = core.Action_Search(M.to_str(query))
        new_model = Dom.Normalize(Dom.Apply(model, action))
        save_state(db, new_model)

        # Extract the query, torrents, and streams from the new model
        (q, torrents, streams) = new_model

        # Convert torrents and streams to JSON-serializable format
        torrents_list = [
            {"id": M.from_str(torrent_id), "title": "torrent_title"} 
            for torrent_id in torrents
        ]
        streams_list = [
            {"id": M.from_str(stream_id), "title": "stream_title"} 
            for stream_id in streams
        ]

        return {
            "query": M.from_str(q),
            "torrents": torrents_list,
            "streams": streams_list
        }

@router.post("/search")
def search_endpoint(query: str):
    try:
        result = search_torrents_and_streaming(query)
        return result
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from fastapi import APIRouter, Body, HTTPException

router = APIRouter()

def sort_torrent_results(results: list[dict[str, str]], sort_by: str) -> list[dict[str, str]]:
    # Validate sort_by parameter
    if sort_by not in ["size", "date", "alphabetical"]:
        raise HTTPException(status_code=400, detail="Invalid sort_by parameter")

    # Handle empty results case
    if not results:
        return []

    # Sort based on the sort_by parameter
    if sort_by == "size":
        # For size sorting, we need to extract numeric values
        def size_to_numeric(size_str):
            size_str = size_str.upper()
            if "GB" in size_str:
                return float(size_str.replace("GB", "")) * 1024
            elif "MB" in size_str:
                return float(size_str.replace("MB", ""))
            elif "KB" in size_str:
                return float(size_str.replace("KB", "")) / 1024
            else:
                return float(size_str)

        return sorted(results, key=lambda x: size_to_numeric(x["size"]), reverse=True)

    elif sort_by == "date":
        # Sort by date (oldest first)
        return sorted(results, key=lambda x: x["date"])

    elif sort_by == "alphabetical":
        # Sort alphabetically by name
        return sorted(results, key=lambda x: x["name"])

    # This should never happen due to validation above
    raise HTTPException(status_code=400, detail="Invalid sort_by parameter")

@router.post("")
def sort_torrent_results_endpoint(
    results: list[dict[str, str]] = Body(..., embed=True),
    sort_by: str = Body(..., embed=True)
):
    try:
        sorted_results = sort_torrent_results(results, sort_by)
        return sorted_results
    except HTTPException as e:
        raise e
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from fastapi import APIRouter, Body, HTTPException
from sqlalchemy import Column, Integer, String
from sqlalchemy.orm import Session
from app.extensions import Base, SessionLocal


class SearchResult(Base):
    __tablename__ = "search_results"
    id = Column(Integer, primary_key=True)
    name = Column(String)
    size = Column(String)


router = APIRouter()


@router.post("")
def paginate_search_results(
    page_number: int = Body(..., embed=True),
    page_size: int = Body(..., embed=True),
    search_query: str = Body(..., embed=True),
) -> dict[str, list[dict[str, str]]]:
    if page_number < 1:
        raise HTTPException(status_code=400, detail="Invalid page number")

    db = SessionLocal()
    try:
        offset = (page_number - 1) * page_size
        query = db.query(SearchResult)

        if search_query:
            query = query.filter(SearchResult.name.contains(search_query))

        results = (
            query
            .offset(offset)
            .limit(page_size)
            .all()
        )

        # Convert the SQLAlchemy objects to dictionaries
        result_dicts = [
            {"name": result.name, "size": result.size}
            for result in results
        ]

        return {"results": result_dicts}
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e))
    finally:
        db.close()

